mapper.select:
SELECT r.id, r.pkg_id, p.name AS pkg_name, r.type, CASE r.type WHEN 0 THEN '软件包' WHEN 1 THEN '固件包' WHEN 2 THEN 'APP包' WHEN 3 THEN 'PC包' ELSE '未知' END AS type_name, r.device_identification, r.device_name, r.product_identification, r.from_version, r.to_version, r.channel, r.phase, CASE r.phase WHEN 0 THEN '检测' WHEN 1 THEN '命中' WHEN 2 THEN '下载完成' WHEN 3 THEN '下载失败' WHEN 4 THEN 'MD5校验失败' WHEN 5 THEN '安装结果' WHEN 6 THEN '启动成功' ELSE '未知' END AS phase_name, r.progress, r.success, r.error_code, r.error_msg, r.cost_ms, r.upgrade_time, r.created_time FROM device_ota_upgrade_record r LEFT JOIN device_ota_pkg p ON p.id = r.pkg_id
AND r.pkg_id = #{pkgId}
AND r.type = #{type}
AND r.device_identification LIKE CONCAT('%', #{deviceIdentification}, '%')
AND r.phase = #{phase}
AND r.success = #{success}
ORDER BY r.created_time DESC

SELECT r.phase, CASE r.phase WHEN 0 THEN '检测' WHEN 1 THEN '命中' WHEN 2 THEN '下载完成' WHEN 3 THEN '下载失败' WHEN 4 THEN 'MD5校验失败' WHEN 5 THEN '安装结果' WHEN 6 THEN '启动成功' ELSE '未知' END AS phase_name, COUNT(DISTINCT r.device_identification) AS device_count FROM device_ota_upgrade_record r WHERE r.pkg_id = #{pkgId}
AND r.upgrade_time >= #{startTime}
GROUP BY r.phase ORDER BY r.phase

SELECT COUNT(DISTINCT r.device_identification)
FROM device_ota_upgrade_record r
WHERE r.pkg_id = #{pkgId} AND r.phase = #{phase}

    AND r.upgrade_time >= #{startTime}

SELECT r.error_code, r.error_msg, COUNT(1) AS count FROM device_ota_upgrade_record r WHERE r.pkg_id = #{pkgId} AND r.error_code IS NOT NULL AND r.error_code != ''
AND r.upgrade_time >= #{startTime}
GROUP BY r.error_code, r.error_msg ORDER BY count DESC LIMIT 10
